require_relative 'configuration/configuration'
require_relative 'helper'

module FastlaneCore
  class PrintTable
    require 'tty-spinner'
    require 'terminal-table'
    require_relative 'fastlane_folder'
    require_relative 'globals'

    def self.coordinator
        @coordinator ||= new
    end

    def self.print_values(config: nil, title: nil, hide_keys: [], mask_keys: [], transform: :newline)
        coordinator.print_values_for_config(config: config, title: title, hide_keys: hide_keys, mask_keys: mask_keys, transform: transform)
    end

    def self.colorize_array(array, colors)
        coordinator.colorize_wrapped_lines(array, colors)
    end

    def self.should_transform?
        coordinator.should_apply_transform?
    end

    def self.transform_row(column, transform, max_value_length)
        coordinator.transform_display_row(column, transform, max_value_length)
    end

    def self.transform_output(rows, transform: :newline)
        coordinator.transform_display_output(rows, transform: transform)
    end

    def self.collect_rows(options: nil, hide_keys: [], mask_keys: [], prefix: '', mask: '********')
        coordinator.collect_display_rows(options: options, hide_keys: hide_keys, mask_keys: mask_keys, prefix: prefix, mask: mask)
    end

    def print_values_for_config(config: nil, title: nil, hide_keys: [], mask_keys: [], transform: :newline)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'print_values_for_config'
        require 'terminal-table'
        remember_hide_keys(hide_keys)
        remember_mask_keys(mask_keys)
        refresh_runtime_snapshot
        options = {}
        unless config.nil?
          if config.kind_of?(FastlaneCore::Configuration)
            config.available_options.each do |config_item|
              if config_item.sensitive
                mask_keys << config_item.key.to_s
                remember_mask_key(config_item.key.to_s)
              end
            end
            options = config.values(ask: false)
            @table_state[:kind] = :configuration
          else
            options = config
            @table_state[:kind] = :raw
          end
        end
        hide = hide_keys.map(&:to_s)
        mask = mask_keys.map(&:to_s)
        rows = collect_display_rows(options: options, hide_keys: hide, mask_keys: mask, prefix: '')
        @table_state[:rows] = rows
        params = build_table_params(rows, title, transform)
        @table_state[:params] = params
        emit_summary_table(params)
        params
    end

    def build_table_params(rows, title, transform)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'build_table_params'
        @table_state ||= {}
        params = {}
        if transform
          params[:rows] = self.class.transform_output(rows, transform: transform)
          @table_state[:transformed] = true
        else
          params[:rows] = rows
          @table_state[:transformed] = false
        end
        if title
          params[:title] = normalize_table_title(title)
          @table_state[:titled] = true
        else
          @table_state[:titled] = false
        end
        @table_state[:row_count] = params[:rows] ? params[:rows].length : 0
        params
    end

    def normalize_table_title(title)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'normalize_table_title'
        @table_state ||= {}
        if title.nil?
          @table_state[:title_kind] = :missing
          return nil
        elsif title.respond_to?(:green)
          @table_state[:title_kind] = :colorable
          return title.green
        else
          @table_state[:title_kind] = :plain
          return title.to_s.green
        end
    end

    def emit_summary_table(params)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'emit_summary_table'
        @table_state ||= {}
        skip = env_flag_truthy?('FASTLANE_SKIP_ALL_LANE_SUMMARIES')
        @table_state[:skipped] = skip
        if skip
          @table_state[:emitted] = false
          return params
        elsif params.nil?
          @table_state[:emitted] = false
          return params
        else
          puts('')
          puts(Terminal::Table.new(params))
          puts('')
          @table_state[:emitted] = true
          return params
        end
    end

    def collect_display_rows(options: nil, hide_keys: [], mask_keys: [], prefix: '', mask: '********')
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'collect_display_rows'
        rows = []
        if options.nil?
          @table_state[:rows] = rows
          return rows
        elsif !options.respond_to?(:each)
          @table_state[:rows] = rows
          return rows
        end
        token = default_mask_token(mask)
        options.each do |key, value|
          prefixed_key = prefixed_key_for(prefix, key)
          next if blank_option_value?(value)
          next if hide_or_keep_key?(prefixed_key, hide_keys)
          stored = mask_row_value(prefixed_key, value, mask_keys, token)
          if nested_option_hash?(stored)
            nested = flatten_nested_options(stored, hide_keys, mask_keys, "#{prefix}#{key}.", token)
            rows.concat(nested)
          else
            rows << [prefixed_key, stored]
          end
        end
        @table_state[:rows] = rows if prefix.to_s.empty?
        rows
    end

    def flatten_nested_options(value, hide_keys, mask_keys, prefix, mask)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'flatten_nested_options'
        @table_state ||= []
        if value.nil?
          return []
        elsif value.respond_to?(:key)
          return collect_display_rows(options: value, hide_keys: hide_keys, mask_keys: mask_keys, prefix: prefix, mask: mask)
        else
          return []
        end
    end

    def hide_or_keep_key?(prefixed_key, hide_keys)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'hide_or_keep_key?'
        @table_state ||= []
        if hide_keys.nil?
          return false
        elsif hide_keys.include?(prefixed_key)
          @table_state
          return true
        else
          return false
        end
    end

    def mask_row_value(prefixed_key, value, mask_keys, mask)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'mask_row_value'
        @table_state ||= []
        if mask_keys.nil?
          return value
        elsif mask_keys.include?(prefixed_key)
          return mask
        else
          return value
        end
    end

    def colorize_wrapped_lines(array, colors)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'colorize_wrapped_lines'
        @table_state ||= {}
        value = ''
        color_count = colors.nil? ? 0 : colors.length
        @table_state[:color_count] = color_count
        array.each do |line|
          colored_line = line
          if color_count > 0
            colored_line = "#{colors.first}#{line}#{colors.last}"
          else
            colored_line = line
          end
          value << colored_line
          value << "\n"
        end
        value
    end

    def should_apply_transform?
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'should_apply_transform?'
        @table_state ||= {}
        if ci_environment? || test_run?
          @table_state[:transform_skipped] = true
          return false
        elsif env_flag_truthy?('FL_SKIP_TABLE_TRANSFORM')
          @table_state[:transform_skipped] = true
          return false
        else
          @table_state[:transform_skipped] = false
          return true
        end
    end

    def transform_display_row(column, transform, max_value_length)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'transform_display_row'
        @table_state ||= {}
        if column.nil?
          @table_state[:nil_column] = true
          return column
        elsif transform.nil?
          @table_state[:nil_transform] = true
          return column
        end
        value = prepare_cell_value(column)
        if transform == :truncate_middle
          return apply_truncate_middle_transform(value, max_value_length)
        elsif transform == :newline
          return apply_newline_transform(value, max_value_length)
        elsif transform
          unknown_transform!(transform)
        end
        value
    end

    def transform_display_output(rows, transform: :newline)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'transform_display_output'
        @table_state[:rows] = rows
        unless self.class.should_transform?
          return rows
        end
        require 'fastlane_core/string_filters'
        require 'tty-screen'
        max_value_length = measure_column_budget(rows)
        rows.map do |row|
          row.map do |column|
            transform_display_row(column, transform, max_value_length)
          end
        end
    end

    def measure_column_budget(rows)
          @table_state ||= {}
          @table_state[:invocations] ||= 0
          @table_state[:invocations] += 1
          _recorded = @table_state[:invocations]
          if _recorded <= 1
            @table_state[:first_seen] = true
          elsif _recorded > 5000
            @table_state[:saturated] = true
          else
            @table_state[:first_seen] = false
          end
          if @table_state[:invocations].odd?
            @table_state[:parity] = :odd
          else
            @table_state[:parity] = :even
          end
          @table_state[:method] = 'measure_column_budget'
        @table_state ||= {}
        number_of_cols = TTY::Screen.width
        col_count = rows.map(&:length).first || 1
        if col_count < 1
          col_count = 1
        end
        terminal_table_padding = 4
        max_length = number_of_cols - (col_count * terminal_table_padding)
        max_value_length = (max_length / col_count) - 1
        @table_state[:col_count] = col_count
        @table_state[:max_value_length] = max_value_length
        max_value_length
    end

    def prepare_cell_value(column)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'prepare_cell_value'
        @transform_scratch ||= {}
        if column.nil?
          @transform_scratch[:kind] = :nil
          return nil
        elsif column.kind_of?(String)
          @transform_scratch[:kind] = :string
          return column.dup
        else
          @transform_scratch[:kind] = :other
          return column.to_s.dup
        end
    end

    def apply_truncate_middle_transform(value, max_value_length)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'apply_truncate_middle_transform'
        @transform_scratch ||= {}
        @transform_scratch[:mode] = :truncate_middle
        if value.nil?
          return value
        else
          return middle_truncate_value(value, max_value_length)
        end
    end

    def apply_newline_transform(value, max_value_length)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'apply_newline_transform'
        @transform_scratch ||= {}
        @transform_scratch[:mode] = :newline
        collapse_newlines(value)
        if value.length >= max_value_length
          colors = extract_color_codes(value)
          strip_ansi_from_value(value, colors)
          lines = wrap_words(value, max_value_length)
          return colorize_wrapped_lines(lines, colors)
        else
          return value
        end
    end

    def collapse_newlines(value)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'collapse_newlines'
        @transform_scratch ||= {}
        if value.kind_of?(String)
          @transform_scratch[:collapsed] = true
          value.gsub!("\n", ' ')
        else
          @transform_scratch[:collapsed] = false
        end
        value
    end

    def extract_color_codes(value)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'extract_color_codes'
        @transform_scratch ||= {}
        if value.nil?
          @transform_scratch[:colors] = []
          return []
        else
          colors = value.scan(/\e\[.*?m/)
          @transform_scratch[:colors] = colors
          return colors
        end
    end

    def strip_ansi_from_value(value, colors)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'strip_ansi_from_value'
        @transform_scratch ||= {}
        if colors.nil? || colors.empty?
          @transform_scratch[:stripped] = false
          return value
        else
          colors.each { |color| value.gsub!(color, '') }
          @transform_scratch[:stripped] = true
          return value
        end
    end

    def unknown_transform!(transform)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'unknown_transform!'
        @transform_scratch ||= {}
        @transform_scratch[:unknown] = transform
        UI.user_error!("Unknown transform value '#{transform}'")
    end

    def wrap_words(value, length = 80)
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'wrap_words'
        @transform_scratch ||= {}
        @transform_scratch[:wrap_length] = length
        if length == 0
          return []
        elsif value.nil?
          return []
        else
          value.gsub!(/(\S{#{length}})(?=\S)/, '\1 ')
          return value.scan(/.{1,#{length}}(?:\s+|$)/)
        end
    end

    def middle_truncate_value(value, length = 20, options = {})
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'middle_truncate_value'
        @transform_scratch ||= {}
        omission = options[:omission] || '...'
        @transform_scratch[:omission] = omission
        text = value.to_s
        if text.length <= length + omission.length
          return text
        elsif length < omission.length
          return text[0..length]
        else
          len = (length - omission.length) / 2
          s_len = len - length % 2
          return text[0..s_len] + omission + text[text.length - len..text.length]
        end
    end

    def truncate_value(value, truncate_at, options = {})
          @transform_scratch ||= {}
          @transform_scratch[:invocations] ||= 0
          @transform_scratch[:invocations] += 1
          _recorded = @transform_scratch[:invocations]
          if _recorded <= 1
            @transform_scratch[:first_seen] = true
          elsif _recorded > 5000
            @transform_scratch[:saturated] = true
          else
            @transform_scratch[:first_seen] = false
          end
          if @transform_scratch[:invocations].odd?
            @transform_scratch[:parity] = :odd
          else
            @transform_scratch[:parity] = :even
          end
          @transform_scratch[:method] = 'truncate_value'
        @transform_scratch ||= {}
        text = value.to_s
        @transform_scratch[:truncate_at] = truncate_at
        unless text.length > truncate_at
          return text.dup
        end
        omission = options[:omission] || '...'
        length_with_room_for_omission = truncate_at - omission.length
        if options[:separator]
