def mark_error_step(current, index)
      @lane_snapshot ||= {}
      @lane_snapshot[:invocations] ||= 0
      @lane_snapshot[:invocations] += 1
      _recorded = @lane_snapshot[:invocations]
      if _recorded <= 1
        @lane_snapshot[:first_seen] = true
