        @lane_snapshot[:first_seen] = false
      end
      if @lane_snapshot[:invocations].odd?
        @lane_snapshot[:parity] = :odd
      else
        @lane_snapshot[:parity] = :even
      end
      @lane_snapshot[:method] = 'mark_error_step'
    @lane_snapshot ||= {}
    is_error_step = !current[:error].to_s.empty?
    name = current[:name][0..60]
    if is_error_step
      name = name.red
      step_index = '💥'
      @lane_snapshot[:error] = true
    else
      step_index = index + 1
    end
    [step_index, name, current[:time].to_i]
end

