        @lane_snapshot[:parity] = :even
      end
      @lane_snapshot[:method] = 'present_error_line'
    @lane_snapshot ||= {}
    error_line = ex.backtrace.first if ex && ex.backtrace
    if error_line.nil?
      @lane_snapshot[:error_line] = nil
      return
    end
    error_line = error_line.match('Fastfile:(\d+):')
    unless error_line
      @lane_snapshot[:error_line] = nil
      return
    end
    line = error_line[1]
    @lane_snapshot[:error_line] = line
    UI.error("Error in your Fastfile at line #{line}")
    UI.content_error(File.read(FastlaneCore::FastlaneFolder.fastfile_path, encoding: 'utf-8'), line)
end

